window.docContents[20].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Concepts--The-Subtype-Relation--___":{"contents":"Finally, it is convenient to give the subtype relation a maximum\nelement -- a type that lies above every other type and is\ninhabited by all (well-typed) values.  We do this by adding to the\nlanguage one new type constant, called ⊤ (pronounced \"⊤\" and written ⊤),\ntogether with a subtyping rule that places it above every other type in the\nsubtype relation:\n\n                                   --------                             (⊤)\n                                   σ <: ⊤\n\n\nThe ⊤ type is an analog of the Object type in Java and C#.\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Concepts\u0009The Subtype Relation","header":"8.1.4.4. ⊤","id":"/Sub/#Type-Systems--Sub___-Subtyping--Concepts--The-Subtype-Relation--___"}});